beforeExample:
public class Example {
    public static void main(String[] args) {
        SashForm mockSashForm = new SashForm();
        mockSashForm.setWeights(new int[] {5,1});
        System.out.println("Weights set to {5,1}");
    }
}

class SashForm {
    private int[] weights;
    public void setWeights(int[] weights) {
        this.weights = weights;
    }
    public int[] getWeights() {
        return weights;
    }
}

